 ruler:'<path d="m3 16 13-13 5 5L8 21Zm4-4 2 2m2-6 2 2m2-6 2 2"/>',
 layers:'<path d="m3 8 9-5 9 5-9 5Zm0 5 9 5 9-5M3 18l9 5 9-5"/>',
 rotate:'<path d="M20 8V3l-3 3a9 9 0 1 0 3 11M20 3h-5"/>',
